                l = mid + 1;
            } else if (n < mid) {
                r = mid - 1;
                answ += 1;
                dir = 'R';
            }
            b--;
        } else {
            if (n < mid) {
                answ += cnt_res(b) + 1;
                r = mid - 1;
            } else if (n > mid) {
                answ += 1;
                l = mid + 1;
                dir = 'L';
            }
            b--;
        }
    }
    cout << answ << "\n";
    return 0;
}
